import copy, json
out=copy.deepcopy(grid)
R,C=len(grid),len(grid[0])
for r in range(R):
    cols=[c for c in range(C) if grid[r][c]==2]
    if len(cols)>=2:
        for c in range(min(cols),max(cols)+1):
            if out[r][c]==1: out[r][c]=3
for c in range(C):
    rows=[r for r in range(R) if grid[r][c]==2]
    if len(rows)>=2:
        for r in range(min(rows),max(rows)+1):
            if out[r][c]==1: out[r][c]=3
print(json.dumps(out))
